inline float uart_cantidad(RbUart& d, const char* bloque) {
    uart_puerto(d, bloque); unsigned int inicio = uart_inicio(d.ultima); bool vacio = true;
    for (unsigned int i = inicio; i < d.ultima.length(); i++) if (d.ultima[i] != ' ') { vacio = false; break; }
    if (vacio) return 0;
    int partes = 1; for (unsigned int i = inicio; i < d.ultima.length(); i++) if (d.ultima[i] == ',') partes++;
    return partes;
}
inline float uart_tipo(RbUart& d, const char* bloque) {
    uart_puerto(d, bloque); unsigned int inicio = uart_inicio(d.ultima); if (!inicio) return 0;
    String cabeza; for (unsigned int i = 0; i + 1 < inicio; i++) cabeza += d.ultima[i];
    char* fin; long tipo = strtol(cabeza.c_str(), &fin, 10);
    return fin != cabeza.c_str() && !*fin ? tipo : 0;
}
// 2.0 → «2» y 1.5 → «1.5», con hasta 3 decimales.
inline String uart_numero(float valor) {
    char texto[24];
    if (fabsf(valor) < 1e9f && valor == float(long(valor))) { snprintf(texto, sizeof texto, "%ld", long(valor)); return String(texto); }
#ifdef ARDUINO
    String decimal = String(valor, 3);  // el printf de AVR no imprime float
#else
    snprintf(texto, sizeof texto, "%.3f", double(valor)); String decimal = texto;
#endif
    unsigned int fin = decimal.length();
    while (fin > 0 && decimal[fin - 1] == '0') fin--;
    if (fin > 0 && decimal[fin - 1] == '.') fin--;
    String corto; for (unsigned int i = 0; i < fin; i++) corto += decimal[i];
    return corto;
}
inline void uart_enviar_datos(RbUart& d, long tipo, bool verificar, const float* datos, int cantidad, const char* bloque) {
    uart_puerto(d, bloque); if (rb_failed) return;
    String texto; char parte[16];
    if (tipo >= 0) { snprintf(parte, sizeof parte, "%ld:", tipo); texto += parte; }
    for (int i = 0; i < cantidad; i++) { if (i) texto += ","; texto += uart_numero(datos[i]); }
    if (verificar) { snprintf(parte, sizeof parte, "*%02X", uart_suma(texto)); texto += parte; }
    d.stream->println(texto);
}

uart_puertos = {}
def uart_suma(texto):
    # Checksum: XOR de todos los bytes antes de «*», en hexadecimal (como NMEA).
    suma = 0
    for byte in texto.encode():
        suma ^= byte
    return suma
def uart_valida(linea):
    # «datos*CC»: devuelve los datos si el checksum coincide; sin «*» se acepta igual.
    if "*" not in linea:
        return linea
    datos, suma = linea.rsplit("*", 1)
    try:
        return datos if len(suma.strip()) == 2 and int(suma, 16) == uart_suma(datos) else None
    except ValueError:
        return None
def uart_puerto(puerto, bloque):
    datos = uart_puertos.get(puerto)
    if datos is None:
        rb_fail(bloque, "Configura UART %s al iniciar" % puerto)
    # Lee sin bloquear y guarda la última línea completa recibida.
    while datos[0].any():
        recibido = datos[0].read()
        if not recibido:
            break
        datos[1] += recibido
    while b"\n" in datos[1]:
        linea, datos[1] = datos[1].split(b"\n", 1)
        try:
            texto = uart_valida(linea.decode().strip())
        except UnicodeError:
            texto = None
        # Las líneas con checksum incorrecto se descartan.
        if texto is not None:
            datos[2] = texto.strip()
            datos[3] = True
    if len(datos[1]) > 512:
        datos[1] = datos[1][-512:]
    return datos
def uart_partes(puerto, bloque):
    # «tipo:d1,d2» → (tipo, ["d1", "d2"]); sin «tipo:» el tipo es 0.
    linea = uart_puerto(puerto, bloque)[2]
    tipo = 0
    if ":" in linea:
        cabeza, linea = linea.split(":", 1)
        try:
            tipo = int(cabeza)
        except ValueError:
            tipo = 0
    return tipo, (linea.split(",") if linea.strip() else [])
def uart_tipo(puerto, bloque):
    return uart_partes(puerto, bloque)[0]

struct RbUart { Stream* stream = nullptr; String buffer, ultima; bool nueva = false; };
// Un objeto por puerto utilizado; no se reservan ocho buffers en UNO/Nano.
inline void uart_configurar(RbUart& datos, Stream& stream) { datos.stream = &stream; datos.buffer = String(); datos.ultima = String(); datos.nueva = false; }
inline bool uart_utf8(const String& text) {
    for (unsigned int i = 0; i < text.length();) {
        unsigned char c = text[i]; unsigned int n = c < 128 ? 1 : c >= 194 && c <= 223 ? 2 : c >= 224 && c <= 239 ? 3 : c >= 240 && c <= 244 ? 4 : 0;
        if (!n || i + n > text.length()) return false;
        for (unsigned int j = 1; j < n; j++) if ((text[i+j] & 192) != 128) return false;
        if (n == 3 && ((c == 224 && (unsigned char)text[i+1] < 160) || (c == 237 && (unsigned char)text[i+1] >= 160))) return false;
        if (n == 4 && ((c == 240 && (unsigned char)text[i+1] < 144) || (c == 244 && (unsigned char)text[i+1] >= 144))) return false;
        i += n;
    } return true;
}
inline bool uart_space(uint32_t c) { return (c >= 9 && c <= 13) || (c >= 28 && c <= 32) || c == 0x85 || c == 0xA0 || c == 0x1680 || (c >= 0x2000 && c <= 0x200A) || c == 0x2028 || c == 0x2029 || c == 0x202F || c == 0x205F || c == 0x3000; }
inline uint8_t uart_suma(const String& texto) { uint8_t suma = 0; for (unsigned int i = 0; i < texto.length(); i++) suma ^= uint8_t(texto[i]); return suma; }
// «datos*CC»: quita el checksum y dice si coincide; sin «*» se acepta igual.
inline bool uart_valida(String& linea) {
    int estrella = -1; for (unsigned int i = 0; i < linea.length(); i++) if (linea[i] == '*') estrella = int(i);
    if (estrella < 0) return true;
    String datos, suma;
    for (int i = 0; i < estrella; i++) datos += linea[i];
    for (unsigned int i = estrella + 1; i < linea.length(); i++) if (linea[i] != ' ' && linea[i] != '\t') suma += linea[i];
    if (suma.length() != 2) return false;
    char* fin; long valor = strtol(suma.c_str(), &fin, 16);
    if (*fin) return false;
    linea = datos;
    return valor == uart_suma(datos);
}
// «tipo:d1,d2»: los datos empiezan después de «:».
inline unsigned int uart_inicio(const String& linea) { for (unsigned int i = 0; i < linea.length(); i++) if (linea[i] == ':') return i + 1; return 0; }
inline RbUart& uart_puerto(RbUart& d, const char* bloque) {
    if (!d.stream) { rb_fail(bloque, "Configura UART al iniciar"); return d; }
    while (d.stream->available() > 0) {
        int value = d.stream->read(); if (value < 0) break;
        if (value == '\n') {
            if (uart_utf8(d.buffer)) {
                unsigned int first = 0, last = 0;
                while (first < d.buffer.length() && uart_space(rb_codepoint(d.buffer, first))) first += rb_utf8_width(d.buffer[first]);
                for (unsigned int i = first; i < d.buffer.length();) { unsigned int end = i + rb_utf8_width(d.buffer[i]); if (!uart_space(rb_codepoint(d.buffer, i))) last = end; i = end; }
                String linea; for (unsigned int i = first; i < last; i++) linea += d.buffer[i]; if (uart_valida(linea)) { d.ultima = linea; d.nueva = true; }
            } d.buffer = String();
        } else {
            d.buffer += char(value);
        }
    }
    if (d.buffer.length() > 512) { String tail; for (unsigned int i = d.buffer.length() - 512; i < d.buffer.length(); i++) tail += d.buffer[i]; d.buffer = tail; }
    return d;
}
inline bool uart_hay_linea(RbUart& d, const char* bloque) { uart_puerto(d, bloque); bool nueva = d.nueva; d.nueva = false; return nueva; }
inline float uart_dato(float numero, RbUart& d, const char* bloque) {
    uart_puerto(d, bloque); int index = int(numero) - 1; if (index < 0) return 0;
    String part; int current = 0;
    for (unsigned int i = uart_inicio(d.ultima); i <= d.ultima.length(); i++) {
        char c = i == d.ultima.length() ? ',' : d.ultima[i];
        if (c == ',') { if (current == index) { char* end; double value = strtod(part.c_str(), &end); while (*end == ' ' || *end == '\r' || *end == '\t') end++; return end != part.c_str() && !*end && isfinite(value) ? value : 0; } current++; part = String(); }
        else part += c;
    } return 0;
}
inline void uart_enviar(RbUart& d, const String& texto, const char* bloque) { uart_puerto(d, bloque); if (!rb_failed) d.stream->println(texto); }
inline void uart_enviar(RbUart& d, float texto, const char* bloque) { uart_enviar(d, rb_to_text(texto, bloque), bloque); }
inline void uart_enviar(RbUart& d, bool texto, const char* bloque) { uart_enviar(d, String(texto ? "True" : "False"), bloque); }
